"""Generate the 2-bit signed-distance atlas for printable ASCII using Pillow."""
from math import hypot
from pathlib import Path

from PIL import Image, ImageDraw, ImageFont

HERE = Path(__file__).resolve().parent
OUTPUT = HERE.parent.parent / "src" / "ui" / "sdf_font.hpp"
WIDTH, HEIGHT = 16, 16
font = ImageFont.truetype(str(HERE / "Inter.ttf"), 16)
font.set_variation_by_axes([16, 450])
lines = [
    "// Generated by assets/font/bake_font.py from Inter. See assets/font/OFL.txt.",
    "#pragma once",
    "#include <array>",
    "#include <cstdint>",
    "",
    "namespace calib::ui {",
    "inline constexpr int glyphWidth = 16;",
    "inline constexpr int glyphHeight = 16;",
    "inline constexpr int averageAdvance = 8;",
    "inline constexpr std::array<int, 95> glyphAdvances{",
    "    " + ", ".join(str(round(font.getlength(chr(code)))) for code in range(32, 127)),
    "};",
    "inline constexpr std::array<std::array<std::uint32_t, 16>, 95> glyphs{{",
]
for code in range(32, 127):
    image = Image.new("L", (WIDTH, HEIGHT))
    ImageDraw.Draw(image).text((0, 12), chr(code), font=font, fill=255, anchor="ls")
    inside = tuple(pixel >= 128 for pixel in image.tobytes())
    words = [0] * 16
    for index, covered in enumerate(inside):
        x, y = index % WIDTH, index // WIDTH
        nearest = min(
            (hypot(x - other % WIDTH, y - other // WIDTH)
             for other, value in enumerate(inside) if value != covered),
            default=2,
        )
        distance = (nearest - 0.5) * (1 if covered else -1)
        sample = max(0, min(3, round(distance + 1.5)))
        words[index // 16] |= sample << (2 * (index % 16))
    lines.append("    {" + ", ".join(f"0x{word:08x}u" for word in words) + f"}}, // {code}")
lines.extend(["}};", "} // namespace calib::ui", ""])
OUTPUT.write_text("\n".join(lines), encoding="utf-8")
